const $=id=>document.getElementById(id),engine=QueueEngine;
const models=[['MM1','M/M/1','Um servidor, capacidade e população ilimitadas.'],['MMs','M/M/s > 1','Vários servidores em paralelo, capacidade ilimitada.'],['MM1K','M/M/1/K','Um servidor e capacidade total K. Chegadas com o sistema cheio são recusadas.'],['MMsK','M/M/s > 1/K','Vários servidores e capacidade total K, incluindo o atendimento.'],['MM1N','M/M/1/N','Um servidor e população finita N de clientes.'],['MMsN','M/M/s > 1/N','Vários servidores e população finita N de clientes.'],['MG1','M/G/1','Um servidor e atendimento com distribuição geral.']];
const units={hora:3600,minuto:60,segundo:1,dia:86400,mes:2592000};
const fields={
 lambda:['Taxa de chegada','λ','rate'],mu:['Taxa de atendimento por servidor','μ','rate'],tmc:['Tempo médio entre chegadas','TMC = 1/λ','time'],tms:['Tempo médio de atendimento','TMS = 1/μ','time'],
 L:['Clientes no sistema','L = E(q)','count'],Lq:['Clientes aguardando na fila','Lq = E(w)','count'],W:['Tempo médio no sistema','W = E(tq)','time'],Wq:['Espera média na fila','Wq = E(tw)','time'],rho:['Ocupação média por servidor','λef/(sμ)','percent'],p0:['Probabilidade de sistema vazio','P₀','percent'],
 load:['Razão de taxas · ρ no formulário','λ/μ','number'],U:['Probabilidade de sistema ocupado','U = 1 − P₀','percent'],effective:['Taxa efetiva de chegada','λef','rate'],busy:['Clientes em atendimento','E(S)','count'],block:['Probabilidade de bloqueio','Pbloqueio','percent'],wait:['Probabilidade de esperar ao entrar','Pespera','percent'],
 cv:['Coeficiente de variação','CV = σ/E(ts)','number'],sd:['Desvio padrão do atendimento','σ','time'],variance:['Variância do atendimento','σ²','squared'],second:['Segundo momento do atendimento','E[ts²]','squared']};
let model=null,timer,epoch=0,observed={},last=null;
const unitName=()=> $('unit').value==='mes'?'mês':$('unit').value;
const f=n=>n.toLocaleString('pt-BR',{maximumFractionDigits:5}),pct=n=>(n*100).toLocaleString('pt-BR',{maximumFractionDigits:2})+'%',time=n=>f(n)+' '+($('unit').value==='mes'?(Math.abs(n-1)<1e-8?'mês':'meses'):unitName()+(Math.abs(n-1)<1e-8?'':'s'));
const options=selected=>Object.keys(units).map(u=>`<option value="${u}" ${u===selected?'selected':''}>${u==='mes'?'Mês (30 dias)':u[0].toUpperCase()+u.slice(1)}</option>`).join('');
function field(key){const [label,symbol,type]=fields[key];const unit=['time','rate','squared'].includes(type)?`<label class="sr" for="${key}-unit">Unidade de ${label}</label><select id="${key}-unit" data-unit="${key}" aria-label="Unidade de ${label}">${options('hora')}</select>`:`<span class="field-suffix">${type==='percent'?'%':type==='count'?'clientes':'sem unidade'}</span>`;return `<div class="data-field"><label for="${key}">${label}<small>${symbol}</small></label><div class="value-unit"><input id="${key}" data-key="${key}" inputmode="decimal" autocomplete="off" placeholder="Não informado">${unit}</div>${type==='rate'?'<span class="unit-hint">clientes por unidade de tempo</span>':type==='squared'?'<span class="unit-hint">unidade de tempo ao quadrado</span>':''}</div>`;}
function buildFields(){
 $('basic-fields').innerHTML=['lambda','mu','tmc','tms'].map(field).join('');
 $('measure-fields').innerHTML=['L','Lq','W','Wq','rho','p0'].map(field).join('');
 $('variance-fields').innerHTML=['cv','sd','variance','second'].map(field).join('');
 $('extra-fields').innerHTML=['load','U','effective','busy',...(model.endsWith('K')?['block']:[]),'wait'].map(field).join('');
 $('count-fields').innerHTML=['arrival','service'].map(key=>`<div class="observation"><h3>${key==='arrival'?'Chegadas observadas'+(model.endsWith('N')?' por cliente fora do sistema':''):'Atendimentos observados por servidor'}</h3><div class="field-grid"><div><label for="${key}-count">Quantidade de clientes</label><input id="${key}-count" inputmode="decimal" placeholder="Não informado"></div><div><label for="${key}-period">Duração do intervalo</label><div class="value-unit"><input id="${key}-period" inputmode="decimal" placeholder="Não informado"><select id="${key}-period-unit" aria-label="Unidade do intervalo de ${key==='arrival'?'chegadas':'atendimentos'}">${options('hora')}</select></div></div></div></div>`).join('');
}
function route(){
 clearTimeout(timer);epoch++;const key=decodeURIComponent(location.hash.replace(/^#\/?/,''));const chosen=models.find(x=>key==='modelo/'+x[0]);
 $('choose-page').hidden=!!chosen;$('calculator-page').hidden=!chosen;$('example').hidden=!chosen;$('print').hidden=!chosen;
 if(!chosen){model=null;document.title='Filas Lab — Escolha o modelo';return;}
 if(model!==chosen[0]){model=chosen[0];$('form').reset();buildFields();$('s-wrap').hidden=!model.includes('s');$('cap-wrap').hidden=!/[KN]$/.test(model);$('cap-label').textContent=model.endsWith('N')?'População finita · N':'Capacidade total · K';$('source-note').hidden=!model.endsWith('N');$('variability').hidden=model!=='MG1';}
 $('model-title').textContent=chosen[1];$('description').textContent=chosen[2];document.title=chosen[1]+' — Filas Lab';resetResults();$('model-title').focus({preventScroll:true});window.scrollTo(0,0);run();
}
function value(id){const raw=$(id).value.trim();if(raw==='')return undefined;const n=Number(raw.replace(',','.'));if(!Number.isFinite(n))throw Error('Preencha '+($(id).labels?.[0]?.textContent||id)+' com um número válido, usando vírgula ou ponto decimal.');return n;}
function collect(){
 const outputSeconds=units[$('unit').value],data={};
 function add(key,n,source){if(n===undefined)return;if(data[key]!==undefined&&Math.abs(n-data[key])>1e-7+.005*Math.max(Math.abs(n),Math.abs(data[key])))throw Error('Dados incompatíveis: '+source+' não corresponde a '+QueueSolver.names[key]+'. Confira os valores e as unidades.');if(data[key]===undefined)data[key]=n;}
 for(const el of $('form').querySelectorAll('[data-key]')){const key=el.dataset.key;if(['cv','sd','variance','second'].includes(key)&&model!=='MG1')continue;let n=value(key);if(n===undefined)continue;if(n<0)throw Error('O campo '+fields[key][0]+' não pode ser negativo.');const type=fields[key][2],factor=$(key+'-unit')?units[$(key+'-unit').value]/outputSeconds:1;
 if(type==='percent')n/=100;if(type==='rate')n/=factor;if(type==='time')n*=factor;if(type==='squared')n*=factor*factor;
 if(key==='tmc'||key==='tms'){if(n<=0)throw Error('Os tempos médios entre chegadas e de atendimento devem ser maiores que zero.');add(key==='tmc'?'lambda':'mu',1/n,fields[key][0]);}else add(key,n,fields[key][0]);}
 for(const key of ['arrival','service']){const n=value(key+'-count'),period=value(key+'-period');if(n===undefined&&period===undefined)continue;if(n===undefined||period===undefined)throw Error('Para usar uma contagem, informe a quantidade e a duração do intervalo.');if(n<=0||period<=0)throw Error('A contagem e a duração do intervalo devem ser maiores que zero.');add(key==='arrival'?'lambda':'mu',n/period*outputSeconds/units[$(key+'-period-unit').value],key==='arrival'?'Contagem de chegadas':'Contagem de atendimentos');}
 return data;
}
function resetResults(){last=null;$('output').innerHTML='';$('error').hidden=true;$('status').textContent='Aguardando dados';$('feedback').textContent='Os campos começam vazios. Preencha os dados conhecidos para ver o que já pode ser calculado.';}
function run(){
 if(!model)return;try{$('month-note').hidden=![...$('form').querySelectorAll('select')].some(el=>el.value==='mes');observed=collect();const config={model,s:model.includes('s')?value('s'):1};if(model.endsWith('K'))config.K=value('cap');if(model.endsWith('N'))config.N=value('cap');
 if((model.includes('s')&&config.s===undefined)||(/[KN]$/.test(model)&&value('cap')===undefined)){$('output').innerHTML='';$('error').hidden=true;$('status').textContent='Defina o sistema';$('feedback').textContent='Informe '+[model.includes('s')?'o número de servidores s':null,model.endsWith('K')?'a capacidade total K':model.endsWith('N')?'a população N':null].filter(Boolean).join(' e ')+'. Depois, preencha os dados que conhece.';last=null;return;}
 if(!Object.keys(observed).length){resetResults();return;}
 const solution=QueueSolver.solve(config,observed);last={solution,config};$('error').hidden=true;$('status').textContent=solution.kind==='complete'?'Cálculo completo':'Cálculo parcial';$('feedback').textContent=solution.kind==='complete'?'Os dados preenchidos foram suficientes para calcular o sistema.':solution.message;render(solution,config);
 }catch(e){last=null;$('output').innerHTML='';$('feedback').textContent='';$('status').textContent='Confira os dados';$('error').textContent=e.message;$('error').hidden=false;}
}
function render(solution,config){const v=solution.values,complete=solution.kind==='complete';
 const definitions=[['lambda','Taxa de chegada','λ','rate'],['mu','Atendimento por servidor','μ','rate'],['effective','Taxa efetiva de chegada','λef','rate'],['L','Clientes no sistema','L = E(q)','count'],['Lq','Clientes aguardando na fila','Lq = E(w)','count'],['busy','Clientes em atendimento','E(S)','count'],['W','Tempo médio no sistema','W = E(tq)','time'],['Wq','Espera média na fila','Wq = E(tw)','time'],['load','Razão λ/μ · ρ no formulário','λ/μ','number'],['rho','Ocupação média por servidor','λef/(sμ)','percent'],['U','Sistema ocupado','U = 1 − P₀','percent'],['p0','Sistema vazio','P₀','percent'],['block','Probabilidade de bloqueio','Pbloqueio','percent'],['wait','Chance de esperar ao entrar','Pespera','percent'],...(model==='MG1'?[['cv','Coeficiente de variação','CV','number'],['sd','Desvio padrão do atendimento','σ','time'],['variance','Variância do atendimento','σ²','squared'],['second','Segundo momento do atendimento','E[ts²]','squared']]:[])];
 const rows=definitions.filter(([key])=>v[key]!==undefined&&v[key]!==null).map(([key,label,sym,type])=>{const val=type==='percent'?pct(v[key]):type==='time'?time(v[key]):type==='rate'?f(v[key])+' /'+unitName():type==='squared'?f(v[key])+' '+unitName()+'²':f(v[key]);return `<tr><td><span class="result-symbol">${sym}</span>${label}<small class="result-origin">${observed[key]!==undefined?'Informado':'Calculado'}</small></td><td>${val}${type==='count'?'<small> clientes</small>':''}</td></tr>`;}).join('');
 $('output').innerHTML=`${rows?`<table class="result-table"><thead><tr><th scope="col">Medida</th><th scope="col">Valor</th></tr></thead><tbody>${rows}</tbody></table>`:''}${v.mu?`<p class="hint">Tempo médio de atendimento (1/μ): ${time(1/v.mu)}.</p>`:''}${v.lambda?`<p class="hint">Tempo médio entre chegadas (1/λ): ${time(1/v.lambda)}${model.endsWith('N')?' por cliente fora do sistema':''}.</p>`:''}${solution.steps.length?`<details><summary>Como os dados foram relacionados</summary><ol>${solution.steps.map(x=>'<li>'+x+'</li>').join('')}</ol></details>`:''}${complete?`<details><summary>Fórmulas deste modelo</summary><p class="formula">${v.method}</p><p>Lei de Little: L = λef W; Lq = λef Wq. Atendimento: W = Wq + 1/μ. E(S) = L − Lq = λef/μ. Nos modelos com população finita, λ é por cliente fora do sistema.</p></details>`:''}<details><summary>Referências e notação</summary><p>Formulário M008 Capítulo 7, páginas 1–3; Teoria das filas Modelo MMs, Prof. Dr. Paulo Roberto Maia, páginas 20–50.</p><p>Equivalências: E(q) = L; E(w) = Lq; E(tq) = W; E(tw) = Wq; E(S) = número em atendimento. O ρ do formulário é λ/μ, não a ocupação por servidor. K é capacidade total; N é população finita.</p><p>Dados adicionais são conferidos com tolerância relativa de 0,5% para arredondamentos. Os resultados usam as equações do modelo; dados ausentes não recebem valores padrão.</p></details>`;
 if(complete&&v.probs)probabilities(v,config);
 if(complete&&(model==='MM1'||model==='MMs'))tails(v);
 if(model==='MG1'){$('output').insertAdjacentHTML('beforeend','<p class="hint">Em M/G/1, média e variância não determinam toda a distribuição P(n). A chance de esperar é igual à ocupação do servidor.</p>');}
}
function probabilities(r,config){
 const box=document.createElement('details');box.innerHTML='<summary>Consultar probabilidade P(n)</summary><label for="query-n">Número de clientes no sistema · n</label><input id="query-n" inputmode="numeric" value="0"><p id="pn"></p><p class="hint">P(n) é a probabilidade de haver exatamente n clientes no sistema.</p>';
 box.innerHTML+=`<div class="chart" role="img" aria-label="Probabilidades de zero a ${Math.min(r.probs.length,30)-1} clientes no sistema">${r.probs.slice(0,30).map((p,n)=>`<div class="bar" style="height:${Math.max(.4,p/Math.max(...r.probs)*100)}%" title="P(${n}) = ${pct(p)}"></div>`).join('')}</div><p class="chart-note">Barras: n = 0 a ${Math.min(r.probs.length,30)-1}. ${!/[KN]$/.test(model)?'A tabela mostra um trecho da distribuição infinita.':''}</p><div style="max-height:220px;overflow:auto"><table><thead><tr><th>n</th><th>P(n)</th></tr></thead><tbody>${r.probs.map((p,n)=>`<tr><td>${n}</td><td>${pct(p)}</td></tr>`).join('')}</tbody></table></div>`;$('output').append(box);
 function show(){try{const n=value('query-n');if(!Number.isInteger(n)||n<0||n>100000)throw Error('Use um inteiro de 0 a 100.000.');let p;if(/[KN]$/.test(model))p=r.probs[n]||0;else{let log=Math.log(r.p0);for(let i=1;i<=n;i++)log+=Math.log(r.lambda/(Math.min(i,r.s)*r.mu));p=Math.exp(log);}$('pn').textContent=`P(${n}) = ${pct(p)}`;}catch(e){$('pn').textContent=e.message;}};$('query-n').oninput=show;show();
}
function tails(r){const box=document.createElement('details');box.innerHTML='<summary>Probabilidades de exceder um limite</summary><label for="threshold">Limite de clientes · r</label><input id="threshold" inputmode="numeric" value="0"><label for="limit">Tempo · '+$('unit').value+'s</label><input id="limit" inputmode="decimal" value="0"><p id="tails"></p>';$('output').append(box);const show=()=>{try{const v=engine.tails(r,value('limit'),value('threshold'));$('tails').textContent='P(n > r) = '+pct(v.count)+' · P(W > t) = '+pct(v.system)+' · P(Wq > t) = '+pct(v.queue);}catch(e){$('tails').textContent=e.message;}};$('limit').oninput=show;$('threshold').oninput=show;show();}
function schedule(){clearTimeout(timer);last=null;$('output').innerHTML='';$('error').hidden=true;$('status').textContent='Atualizando';$('feedback').textContent='Relacionando os dados preenchidos…';const current=++epoch;timer=setTimeout(()=>{if(epoch===current)run();},400);}
function clear(){clearTimeout(timer);epoch++;$('form').reset();resetResults();run();}
 $('model-choices').innerHTML=models.map(([key,label,desc])=>`<a class="model-choice" href="#/modelo/${key}"><span class="choice-model">${label}</span><span>${desc}</span><svg width="22" height="22" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h15m-6-6 6 6-6 6" fill="none" stroke="currentColor" stroke-width="1.5"/></svg></a>`).join('');
 $('form').addEventListener('input',schedule);$('form').addEventListener('change',schedule);$('form').addEventListener('submit',e=>{e.preventDefault();clearTimeout(timer);epoch++;run();if(window.innerWidth<=850)$('results-title').scrollIntoView({block:'start'});});$('clear').onclick=clear;
 $('example').onclick=()=>{clear();if(model.includes('s'))$('s').value='2';if(/[KN]$/.test(model))$('cap').value='10';$('lambda').value=model.endsWith('N')?'0,2':'3';$('mu').value='4';if(model==='MG1')$('cv').value='1';run();};
 $('print').onclick=()=>window.print();window.addEventListener('hashchange',route);route();
